// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import java.io.IOException;

import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierFallbackReason;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierStatisticsException;

/**
 * Pure scheduling decisions for the background Frontier Statistics V2 lifecycle.
 *
 * <p>
 * Base rebuilds are debounced behind a quiet period so that bursts of commits coalesce, but the debounce carries a
 * deadline: once a base rebuild has been pending for the maximum deferral it starts even while commits keep arriving,
 * because every commit resets the quiet period and a steady trickle of writes would otherwise starve the rebuild
 * forever. Delta publication failures are classified into failures that can never succeed against the current base
 * (typed permanent failures and layer exhaustion), which escalate to a base rebuild immediately, and transient
 * failures, which are retried a bounded number of times before they escalate too.
 * </p>
 */
final class FrontierRebuildSchedulePolicy {

	private FrontierRebuildSchedulePolicy() {
	}

	/**
	 * Decides whether a required base rebuild may start now.
	 *
	 * @param nowNanos             the current {@link System#nanoTime()}
	 * @param lastRequestNanos     when the most recent commit (or explicit request) asked for a refresh
	 * @param pending              whether a base rebuild has been determined to be required
	 * @param pendingSinceNanos    when that requirement was first observed; ignored unless {@code pending}
	 * @param quietPeriodNanos     the debounce window measured from the last request
	 * @param maximumDeferralNanos the longest a pending base rebuild may be deferred by fresh requests
	 * @return {@code true} when the quiet period has elapsed or the pending rebuild has reached its deadline
	 */
	static boolean shouldStartBaseRebuild(long nowNanos, long lastRequestNanos, boolean pending,
			long pendingSinceNanos, long quietPeriodNanos, long maximumDeferralNanos) {
		if (nowNanos - lastRequestNanos >= quietPeriodNanos) {
			return true;
		}
		return pending && nowNanos - pendingSinceNanos >= maximumDeferralNanos;
	}

	/**
	 * Classifies a failed signed-delta publication.
	 *
	 * @param failure                      the failure raised while building or publishing the delta
	 * @param consecutiveTransientFailures how many consecutive publications of the same uncovered range have already
	 *                                     failed transiently, including this one
	 * @param maximumTransientFailures     the bound after which transient failures escalate as well
	 * @return {@code true} when the store must fold the journal into a fresh base instead of retrying the delta
	 */
	static boolean deltaFailureRequiresBaseRebuild(IOException failure, int consecutiveTransientFailures,
			int maximumTransientFailures) {
		if (failure instanceof FrontierStatisticsException typed
				&& (typed.requiresBaseRebuild()
						|| typed.fallbackReason() == FrontierFallbackReason.CONFIDENCE_TOO_WIDE)) {
			return true;
		}
		return consecutiveTransientFailures >= maximumTransientFailures;
	}
}
